export function bindTouch(canvas,universe,sensors){let down=false,start=0,longTimer=null,last={x:0,y:0};canvas.addEventListener('pointerdown',e=>{down=true;start=Date.now();last={x:e.clientX,y:e.clientY};longTimer=setTimeout(()=>universe.setAttractor(ndc(e,canvas),1),420);});canvas.addEventListener('pointermove',e=>{if(!down)return;const dx=(e.clientX-last.x)/canvas.clientWidth;const dy=(e.clientY-last.y)/canvas.clientHeight;last={x:e.clientX,y:e.clientY};if(!sensors?.enabled)universe.nudgeField(dx,-dy);});canvas.addEventListener('pointerup',e=>{clearTimeout(longTimer);if(Date.now()-start<250)universe.pulse(ndc(e,canvas));universe.clearAttractor();down=false;});window.addEventListener('keydown',e=>{if(e.key===' ')universe.burst();if(e.key==='r'||e.key==='R')universe.reset();});}
function ndc(e,c){const r=c.getBoundingClientRect();return{x:((e.clientX-r.left)/r.width)*2-1,y:-((e.clientY-r.top)/r.height)*2+1};}
